// The Error Trigger hands over the failed execution. Normalize it into one
// record that is easy to store and easy to read in Slack.
const j = $input.first().json || {};
const exec = j.execution || {};
const wfObj = j.workflow || {};
const err = exec.error || {};
return [{
  json: {
    workflow: wfObj.name || 'unknown workflow',
    node: exec.lastNodeExecuted || 'unknown node',
    error: String(err.message || err.description || 'Unknown error').slice(0, 800),
    executionId: exec.id || null,
    executionUrl: exec.url || null,
    mode: exec.mode || 'unknown',
    time: new Date().toISOString(),
  },
}];
